'use strict';
const KEY='lifeos.data.v1.'+window.lifeosUserId, TODAY=()=>localDate(new Date()), START='2026-11-20';
const categories=['Internship','Academics','Technical learning','Personal projects','Gym','Mother','Family','Girlfriend','Friends','Entertainment','Gaming','Travel','Errands','Rest','Sleep','Other'];
const expenseCats=['Food','Transport','Gym','Shopping','Entertainment','Travel','Education','Other'];
const projects=['RISC-V architecture','AI-assisted multicore scheduling','Verilog projects','UART IP','OpenROAD and Yosys experiments'];
const blank=()=>({version:1,activities:[],logs:[],learning:[],projects:projects.map((name,i)=>({id:'seed'+i,name,status:'Not started',progress:null,notes:''})),workouts:[],relationships:[],expenses:[],reviews:{},budget:0,internshipHours:'Unconfirmed',theme:'dark',sharedSpaces:[]});
let db=load(),tab='home',date=TODAY(),trackTab='insights',filter='All',search='',weekOffset=0,calendarMonth=TODAY().slice(0,7);
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&x.version===1&&Array.isArray(x.activities)&&Array.isArray(x.logs))return {...blank(),...x,sharedSpaces:Array.isArray(x.sharedSpaces)?x.sharedSpaces:[]}}catch(e){}return blank()}
function save(){localStorage.setItem(KEY,JSON.stringify(db));render();if(typeof cloudChanged==='function')cloudChanged()}
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtDate(d){return new Date(d+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function timeMinutes(t){const p=String(t||'').split(':').map(Number);return p.length===2&&p.every(Number.isFinite)?p[0]*60+p[1]:NaN}
function addDays(d,n){const day=new Date(d+'T12:00:00');day.setDate(day.getDate()+n);return localDate(day)}
function mins(a,b){if(!a||!b)return 0;const x=timeMinutes(a),y=timeMinutes(b);if(!Number.isFinite(x)||!Number.isFinite(y))return 0;return (y-x+1440)%1440}
function activityMinutes(x){const span=LifeOSTime.scheduledInterval(x);return span?Math.round((span.end-span.start)/60000):0}
function dailyPlannedMinutes(x,day){return LifeOSTime.plannedMinutes(x,day)}
function dailyPlannedActivities(day){return db.activities.filter(x=>x.date===day||dailyPlannedMinutes(x,day)>0)}
function endLabel(x){return x.end?(x.endDate&&x.endDate!==x.date?x.end+' ('+x.endDate+')':x.end):''}
function hours(n){return (n/60).toFixed(1)+'h'}
function rupee(n){return '₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2})}
function id(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function entries(type,d=date){return db[type].filter(x=>x.date===d)}
function totalActual(a){return a.reduce((n,x)=>n+(Number(x.actual)||0),0)}
function actualFor(d){return [...db.logs.map(x=>({...x,collection:'logs'})),...db.activities.filter(x=>x.status==='completed')].reduce((sum,x)=>sum+LifeOSTime.actualMinutes(x,d),0)}
function periodDays(offset=0){let d=new Date(date+'T12:00:00');let day=(d.getDay()+6)%7;d.setDate(d.getDate()-day+offset*7);return Array.from({length:7},(_,i)=>{let a=new Date(d);a.setDate(d.getDate()+i);return localDate(a)})}
function weekly(type,days){return db[type].filter(x=>days.includes(x.date))}
function section(title,content,cls='span12'){return `<section class="card ${cls}"><h2>${title}</h2>${content}</section>`}
function empty(msg='Nothing logged yet. Start when you are ready.'){return `<div class="empty">${msg}</div>`}
function btn(label,action,cls='secondary small'){return `<button class="${cls}" data-action="${action}">${label}</button>`}
function heading(title,subtitle,action=''){return `<div class="heading"><div><div class="eyebrow">PERSONAL LIFE OPERATING SYSTEM</div><h1>${title}</h1><p class="muted">${subtitle}</p></div>${action}</div>`}
function rows(items,type,renderItem){return items.length?items.map(x=>`<div class="rowitem"><div class="dot"></div><div class="rowbody">${renderItem(x)}</div><button class="secondary small" data-edit="${type}:${esc(x.id)}">Edit</button></div>`).join(''):empty()}
function dateNav(){return `<div class="datebar"><button class="secondary small" data-action="prevday">←</button><input aria-label="Selected date" type="date" id="datePick" value="${date}"><button class="secondary small" data-action="nextday">→</button>${btn('Today','today')}</div>`}
function home(){
 const a=dailyPlannedActivities(date);
 const progress=LifeOSTime.statusMetrics(a);
 const done=progress.done;
 const pending=progress.planned+progress.active;
 const percent=progress.percent;
 const planned=a.reduce((sum,x)=>sum+dailyPlannedMinutes(x,date),0);
 const actual=actualFor(date);
 const expenses=entries('expenses').reduce((sum,x)=>sum+Number(x.amount||0),0);
 const gym=entries('workouts').length;
 const learning=totalActual(entries('learning'));
 const people=entries('relationships').length;
 const measured=a.filter(x=>x.status==='completed').reduce((n,x)=>n+LifeOSTime.measuredMinutes(x,date),0);
 const ahead=a.filter(x=>x.status==='completed').map(x=>LifeOSTime.scheduleVariance(x)).filter(n=>n!==null&&n>0);
 const earlyCount=ahead.length;
 const all=[...a.map(x=>({...x,source:'activities',start:x.date!==date?'00:00':x.start})),...entries('logs').map(x=>({...x,source:'logs'}))].sort((x,y)=>(x.start||'99:99').localeCompare(y.start||'99:99'));
 const upcoming=a.filter(x=>['planned','in_progress','paused'].includes(x.status)).sort((x,y)=>(x.start||'99:99').localeCompare(y.start||'99:99'));
 const now=new Date(),nowMinute=now.getHours()*60+now.getMinutes();
 const next=date===TODAY()?(upcoming.find(x=>x.status==='in_progress'||x.status==='paused'||(x.start&&timeMinutes(x.start)>=nowMinute))||upcoming[0]):upcoming[0];
 const dayName=new Date(date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long',month:'long',day:'numeric'});
 const greeting=date===TODAY()?(new Date().getHours()<12?'Good morning.':new Date().getHours()<17?'Good afternoon.':'Good evening.'):'Your day, in focus.';
 const ring=`<button type="button" class="life-ring life-ring-button" data-action="ringDetails" title="Open progress details" style="--ring:${percent}%" aria-label="View progress details: ${percent}% complete"><div class="life-ring-inner"><strong>${a.length?percent+'%':'—'}</strong><small>VIEW DETAILS</small></div></button>`;

 const v3Glyph=(name)=>`<svg class="v3-icon" aria-hidden="true"><use href="#v3-${name}"></use></svg>`;
 const metric=(icon,label,value,detail,accent)=>`<div class="focus-tile ${accent}"><div class="focus-icon">${icon}</div><div class="focus-label">${label}</div><strong>${value}</strong><small>${detail}</small></div>`;
 const timeline=all.length?all.map(x=>`<div class="life-timeline-row"><div class="life-time">${esc(x.start||'Flexible')}</div><div class="life-rail"><span class="life-rail-dot ${x.status==='completed'?'is-done':''}"></span></div><div class="life-timeline-content"><strong>${esc(x.title)}</strong><small>${esc(x.category||'Activity')} · ${x.end?esc(endLabel(x)):x.source==='logs'?'Actual log':esc(x.status||'planned')}</small></div><button class="secondary small" data-edit="${x.source}:${esc(x.id)}">Edit</button></div>`).join(''):empty('Your timeline is waiting. Add your first activity to shape the day.');
 return `<div class="life-home"><div class="life-welcome"><div><div class="eyebrow">${esc(dayName)} · LIFEOS</div><h1>${greeting}</h1><p class="muted">A little progress, a little balance, every day.</p></div><div class="life-date-controls">${dateNav()}</div></div>
 <div class="life-home-grid">
 <section class="card life-progress-card"><div class="life-card-heading"><div><div class="kicker">YOUR DAY</div><h2>Today's progress</h2></div><span class="life-soft-tag">${a.length} planned</span></div><div class="life-progress-body">${ring}<div class="life-progress-stats"><div><span class="life-status-dot done"></span><strong>${done}</strong> completed</div><div><span class="life-status-dot pending"></span><strong>${pending}</strong> remaining</div><div><span class="life-status-dot muted-dot"></span><strong>${progress.skipped}</strong> skipped</div></div></div><div class="life-card-footer">${a.length?'Progress reflects completed planned activities.':'Nothing planned yet. Start with one meaningful thing.'}</div></section>
 <section class="card life-next-card"><div class="life-card-heading"><h2>Up next</h2><button class="life-text-button" data-action="goPlanner">View plan →</button></div>${next?`<div class="life-next-detail"><div class="life-next-icon"><svg class="v3-icon" aria-hidden="true"><use href="#v3-sparkles"></use></svg></div><div><div class="life-next-title">${esc(next.title)}</div><div class="sub">${esc(next.category)} · ${esc(next.start||'Flexible')}${next.end?' – '+esc(next.end):''}</div><span class="life-soft-tag">${esc(next.priority||'Normal')} priority</span></div></div><div class="life-next-actions">${next.status==='planned'?btn('▶ Start','start:'+next.id,'secondary small'):next.status==='in_progress'?btn('Ⅱ Pause','pause:'+next.id,'secondary small'):next.status==='paused'?btn('▶ Resume','start:'+next.id,'secondary small'):''}${btn('✓ Complete','status:'+next.id+':completed','primary small')}${btn('Edit','editNext','secondary small')}</div>`:`<div class="life-next-empty"><img class="v3-empty-illustration" src="illustrations/focus.png" alt=""><strong>Space to breathe.</strong><p>${a.length?'No more planned activities for this day.':'Your next meaningful activity starts here.'}</p></div>${btn('Plan an activity','add:activities','primary small')}`}</section>
 <section class="life-focus-section"><div class="life-section-heading"><h2>Today’s intelligence</h2><span class="sub">Plans and evidence stay distinct</span></div><div class="life-focus-grid">${metric(v3Glyph('check'),'Completed',done+' / '+a.length,'Activities marked done','green')}${metric(v3Glyph('track'),'Time scheduled',hours(planned),'Across this calendar day','amber')}${metric(v3Glyph('chart'),'Time recorded',actual?hours(actual):'—',actual?'Explicitly logged / measured':'No duration evidence yet','blue')}${metric(v3Glyph('sparkles'),'Finished early',earlyCount?earlyCount+' activity'+(earlyCount===1?'':'ies'):'—','Schedule boundary; not speed score','rose')}</div></section>
 <section class="card life-timeline-card"><div class="life-card-heading"><h2>Today's timeline</h2><button class="life-text-button" data-action="goPlanner">Full planner →</button></div><div class="life-timeline">${timeline}</div><div class="life-quick-actions">${btn('↻ Reschedule','reschedule','secondary small')}${btn('＋ Plan activity','add:activities','primary small')}${btn('＋ Quick log','add:logs','secondary small')}</div></section>
 <section class="card life-insights-card"><div class="life-card-heading"><h2>Time & attention</h2><span class="life-soft-tag">Today</span></div><div class="life-mini-stat"><span>Planned duration</span><strong>${hours(planned)}</strong></div><div class="life-mini-stat"><span>Observed / entered duration</span><strong>${actual?hours(actual):'Not recorded'}</strong></div><div class="life-mini-stat"><span>Timer-measured today</span><strong>${measured?hours(measured):'—'}</strong></div><div class="life-mini-stat"><span>Expenses</span><strong>${rupee(expenses)}</strong></div><div class="life-category-bars"><div class="sub" style="margin:12px 0 6px">Planned time by category</div>${plannedCategoryBars(date)}<div class="sub" style="margin:14px 0 6px">Actual recorded by category</div>${categoryBars(date)}</div></section>
 <section class="card life-reminder-card v3-copilot-card"><img class="v3-copilot-illustration" src="illustrations/technical.png" alt="" loading="lazy"><div class="life-card-heading"><h2>LifeOS Copilot</h2><button class="life-text-button" data-action="copilot">Open →</button></div><p>Plan naturally, review AI suggestions, or make room for what matters.</p><div class="life-quick-actions">${btn('✦ Plan with AI','copilot','primary small')}</div></section><section class="card life-reminder-card"><div class="kicker">A GENTLER REMINDER</div><p>Rest, relationships, and joy belong in your plans, too.</p><small>Progress is information, never a measure of your worth.</small></section>
 </div></div>`;
}
function plannedCategoryBars(day){
 const vals={};for(const x of dailyPlannedActivities(day)){const n=dailyPlannedMinutes(x,day);if(n)vals[x.category||'Other']=(vals[x.category||'Other']||0)+n}
 const arr=Object.entries(vals).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...arr.map(x=>x[1]));
 return arr.length?arr.map(([name,value])=>`<div class="barline"><span>${esc(name)}</span><div class="progress"><div style="width:${100*value/max}%"></div></div><b>${hours(value)}</b></div>`).join(''):empty('No timed activities planned for this date.');
}
function categoryBars(dates){let ds=Array.isArray(dates)?dates:[dates],vals={};[...db.logs.map(x=>({...x,collection:'logs'})),...db.activities.filter(x=>x.status==='completed')].forEach(x=>{const n=ds.reduce((sum,d)=>sum+LifeOSTime.actualMinutes(x,d),0);if(n)vals[x.category||'Other']=(vals[x.category||'Other']||0)+n});let arr=Object.entries(vals).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...arr.map(x=>x[1]));return arr.length?arr.map(([name,value])=>`<div class="barline"><span>${esc(name)}</span><div class="progress"><div style="width:${100*value/max}%"></div></div><b>${hours(value)}</b></div>`).join(''):empty('No measured or manually recorded duration for this period.')}
function domainInsights(){
 const days=periodDays(),all=[...db.activities,...db.logs.map(x=>({...x,collection:'logs'}))];
 const summary=LifeOSDomains.summarize(all,days,LifeOSTime);
 const weekLabel=`${days[0]} – ${days[6]}`;
 const totals=summary.reduce((a,g)=>({planned:a.planned+g.planned,recorded:a.recorded+g.recorded,measured:a.measured+g.measured,unknown:a.unknown+g.unknown,completed:a.completed+g.completed}),{planned:0,recorded:0,measured:0,unknown:0,completed:0});
 const cards=summary.map(g=>`<article class="domain-insight"><div class="domain-insight-head"><strong>${esc(g.label)}</strong><span class="life-soft-tag">${g.completed} completed${g.logs?' · '+g.logs+' logs':''}</span></div><div class="domain-insight-stats"><span>Scheduled <b>${hours(g.planned)}</b></span><span>Recorded <b>${hours(g.recorded)}</b></span><span>Timer-measured <b>${hours(g.measured)}</b></span></div>${g.unknown?`<p class="sub">${g.unknown} completed without a recorded duration</p>`:''}${g.skipped?`<p class="sub">${g.skipped} skipped — not counted as completed</p>`:''}<p class="sub domain-guidance">${esc(LifeOSDomains.outcomes[g.domain])}</p></article>`).join('');
 return section('Your life domains',`<p class="sub">${esc(weekLabel)} · Uses existing categories and optional domain overrides. No universal productivity score.</p><div class="domain-summary"><div><small>Scheduled</small><strong>${hours(totals.planned)}</strong></div><div><small>Recorded</small><strong>${hours(totals.recorded)}</strong></div><div><small>Timer-measured</small><strong>${hours(totals.measured)}</strong></div><div><small>Completed</small><strong>${totals.completed}</strong></div></div>${totals.unknown?`<div class="notice">${totals.unknown} completed activities have no recorded duration. Completion still counts.</div>`:''}<div class="domain-insight-grid">${cards||empty('No activities in this week yet. Your insights will appear as you plan and log.')}</div><p class="sub">Recorded time is measured or user-entered, not automatically inferred from scheduled blocks. Domain guidance is descriptive, not a judgment.</p>`);
}
function planner(){let a=dailyPlannedActivities(date).filter(x=>(filter==='All'||x.category===filter)&&(`${x.title} ${x.notes||''}`.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>(a.start||'99').localeCompare(b.start||'99'));
return heading('Daily planner','Make a plan. Change it freely.',dateNav())+`<div class="grid">${section('Plan your day',`<div class="flex">${btn('＋ Add activity','add:activities','primary small')}<input class="search" id="search" placeholder="Search activities" value="${esc(search)}"><select id="filter" style="width:auto"><option>All</option>${categories.map(c=>`<option ${filter===c?'selected':''}>${c}</option>`).join('')}</select></div>${rows(a,'activities',x=>`<strong>${esc(x.title)}</strong><small>${esc(x.category)} · ${esc(LifeOSDomains.labels[LifeOSDomains.infer(x)])} · ${esc(x.start||'Flexible')}${x.end?'–'+esc(endLabel(x)):''} · ${esc(x.priority||'Normal')} · ${esc(x.status||'planned')} · ${hours(dailyPlannedMinutes(x,date))} planned on selected day · ${Number(x.actual)>0?hours(x.actual)+' recorded': 'duration not recorded'}${x.date!==date?' · Continues from '+esc(x.date):''}</small><div class="flex" style="margin-top:7px">${x.status==='planned'?btn('▶ Start','start:'+x.id):''}${x.status==='in_progress'?btn('Ⅱ Pause','pause:'+x.id):''}${x.status==='paused'?btn('▶ Resume','start:'+x.id):''}${x.status!=='completed'?btn('✓ Complete','status:'+x.id+':completed'):''}${x.status!=='skipped'?btn('Skip','status:'+x.id+':skipped'):btn('Log replacement','replacement:'+x.id)}${x.status!=='planned'?btn('Reset','status:'+x.id+':planned'):''}</div>`)}<div class="sub">You can reschedule any activity by editing its time. Flexible activities can have no assigned hours.</div>`,'span8')}${section('Calendar',calendar(),'span4')}${section('A flexible internship transition',`<div class="notice">Internship hours are <strong>${esc(db.internshipHours)}</strong>. Plan around your energy, not an assumed 9-to-5. Once confirmed, update the hours in Settings and adjust activities without deleting logs.</div>`,'span12')}</div>`}
function calendar(){let [y,m]=calendarMonth.split('-').map(Number),first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),offset=(first.getDay()+6)%7,labels=['M','T','W','T','F','S','S'];let out=`<div class="flex between"><button class="secondary small" data-action="prevmonth">←</button><strong>${first.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</strong><button class="secondary small" data-action="nextmonth">→</button></div><div class="calendar">${labels.map(x=>`<div class="calendarlabel">${x}</div>`).join('')}${Array.from({length:offset},()=>'<div></div>').join('')}`;for(let i=1;i<=days;i++){let d=`${y}-${String(m).padStart(2,'0')}-${String(i).padStart(2,'0')}`;out+=`<button class="day ${d===date?'selected':''} ${(dailyPlannedActivities(d).length||['logs','expenses','learning','workouts','relationships'].some(k=>entries(k,d).length))?'hasdata':''}" data-date="${d}">${i}</button>`}return out+'</div>'}
function logger(){let l=entries('logs').sort((a,b)=>(a.start||'').localeCompare(b.start||''));return heading('Activity journal','Record real life, even when it was not planned.',dateNav())+`<div class="grid">${section('Quick activity logger',`${btn('＋ Log actual activity','add:logs','primary')}<p class="sub">Retrospective logs are welcome. You do not need a task for every moment.</p>${rows(l,'logs',x=>`<strong>${esc(x.title)}</strong><small>${esc(x.category)} · ${esc(x.start||'No start')}${x.end?'–'+esc(endLabel(x)):''} · ${hours(x.actual||0)} actual</small>${x.notes?`<small>${esc(x.notes)}</small>`:''}`)}`,'span7')}${section('Actual time by category',categoryBars(date),'span5')}</div>`}
function track(){let options=[['insights','Insights'],['learning','Learning'],['projects','Projects'],['workouts','Fitness'],['relationships','People'],['expenses','Finance']];let content=trackTab==='insights'?domainInsights():trackTab==='learning'?learning():trackTab==='projects'?projectView():trackTab==='workouts'?fitness():trackTab==='relationships'?people():finance();return heading('Life trackers','The parts of life that matter to you.')+`<div class="chips">${options.map(([v,n])=>`<button class="chip ${trackTab===v?'active':''}" data-track="${v}">${n}</button>`).join('')}</div><div class="grid">${content}</div>`}
function learning(){let days=periodDays(),weeklyHours=totalActual(weekly('learning',days));return section('Learning sessions',`${btn('＋ Add study session','add:learning','primary small')}<p class="sub">This week: ${hours(weeklyHours)} of dedicated learning</p>${rows(db.learning.slice().sort((a,b)=>b.date.localeCompare(a.date)),'learning',x=>`<strong>${esc(x.subject)} · ${esc(x.topic)}</strong><small>${esc(x.date)} · ${hours(x.actual)} · ${esc(x.status||'In progress')} ${x.revision?'· Revision needed':''}</small><small>${esc(x.resource||'')}${x.notes?' · '+esc(x.notes):''}</small>`)}`,'span8')+section('Weekly learning',categoryBars(days),'span4')}
function projectView(){return section('Technical projects',`${btn('＋ Add project','add:projects','primary small')}${rows(db.projects,'projects',x=>`<strong>${esc(x.name)}</strong><small>${esc(x.status)} · ${x.progress==null?'Progress not set':x.progress+'%'}</small>${x.progress!=null?`<div class="progress" style="margin-top:8px"><div style="width:${x.progress}%"></div></div>`:''}<small>${esc(x.notes||'')}</small>`)}`)}
function fitness(){let w=db.workouts.slice().sort((a,b)=>b.date.localeCompare(a.date)),days=periodDays(),freq=weekly('workouts',days).length;let lift=['Bench press','Squat','Deadlift','Pulling'];let chart=lift.map(n=>{let pts=w.filter(x=>x.exercise?.toLowerCase().includes(n.toLowerCase().split(' ')[0])&&Number(x.weight)>0).sort((a,b)=>a.date.localeCompare(b.date));return `<div class="barline"><span>${n}</span><div class="progress"><div style="width:${pts.length?Math.min(100,pts.at(-1).weight/Math.max(...pts.map(x=>x.weight))*100):0}%"></div></div><b>${pts.length?pts.at(-1).weight+'kg':'—'}</b></div>`}).join('');return section('Workout journal',`${btn('＋ Log workout','add:workouts','primary small')}<p class="sub">This week: ${freq} session(s). Recovery days are valid days.</p>${rows(w,'workouts',x=>`<strong>${esc(x.type)} · ${esc(x.exercise||'Recovery')}</strong><small>${esc(x.date)} · ${x.sets||0} sets × ${x.reps||0} reps · ${x.weight||0} kg · ${hours(x.actual||0)}</small><small>Body weight: ${x.bodyweight||'—'} kg · Recovery: ${esc(x.recovery||'Not specified')} ${x.pr?'· PR':''}</small>`)}`,'span7')+section('Latest recorded lifts',chart+'<p class="sub">Latest recorded weights, not strength scores. Compare your individual workout entries for progression.</p>','span5')}
function people(){return section('People & memories',`${btn('＋ Add a moment','add:relationships','primary small')}<p class="sub">A journal of connection, not a relationship score.</p>${rows(db.relationships.slice().sort((a,b)=>b.date.localeCompare(a.date)),'relationships',x=>`<strong>${esc(x.person)} · ${esc(x.kind)}</strong><small>${esc(x.date)} · ${hours(x.actual||0)}</small><small>${esc(x.notes||'')}</small>`)}`)}
function finance(){let d=entries('expenses').reduce((s,x)=>s+Number(x.amount),0),days=periodDays(),w=weekly('expenses',days).reduce((s,x)=>s+Number(x.amount),0),month=db.expenses.filter(x=>x.date.startsWith(date.slice(0,7))).reduce((s,x)=>s+Number(x.amount),0),budget=Number(db.budget||0);let cats={};db.expenses.filter(x=>x.date.startsWith(date.slice(0,7))).forEach(x=>cats[x.category]=(cats[x.category]||0)+Number(x.amount));let max=Math.max(1,...Object.values(cats));return section('Expenses',`${btn('＋ Add expense','add:expenses','primary small')}<div class="grid sectiongap"><div class="span4"><div class="kicker">Today</div><div class="metric">${rupee(d)}</div></div><div class="span4"><div class="kicker">This week</div><div class="metric">${rupee(w)}</div></div><div class="span4"><div class="kicker">This month</div><div class="metric">${rupee(month)}</div></div></div>${rows(db.expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)),'expenses',x=>`<strong>${rupee(x.amount)} · ${esc(x.category)}</strong><small>${esc(x.date)} · ${esc(x.method)} · ${esc(x.description||'')}</small>`)}`,'span7')+section('Monthly budget',`<div class="metric">${budget?rupee(month)+' / '+rupee(budget):'Not set'}</div>${budget?`<div class="progress"><div style="width:${Math.min(100,100*month/budget)}%"></div></div>`:''}<div class="field"><label for="budget">Monthly budget (₹)</label><input id="budget" type="number" min="0" step="1" value="${db.budget||''}" placeholder="Optional"></div>${btn('Save budget','budget')}<h2 class="sectiongap">Spending categories</h2>${Object.entries(cats).map(([k,v])=>`<div class="barline"><span>${esc(k)}</span><div class="progress"><div style="width:${100*v/max}%"></div></div><b>${rupee(v)}</b></div>`).join('')||empty()}`,'span5')}
function review(){let days=periodDays(weekOffset),a=weekly('activities',days),l=weekly('logs',days),w=weekly('workouts',days),e=weekly('expenses',days),learn=weekly('learning',days),rel=weekly('relationships',days),all=[...l,...a.filter(x=>x.status==='completed')],cat=n=>hours(all.filter(x=>n.includes(x.category)).reduce((s,x)=>s+Number(x.actual||0),0));let r=db.reviews[date]||{};return heading('Reflect, not judge','Notice what matters. Adjust gently.',dateNav())+`<div class="grid">${section('Daily reflection',`<div class="sub">${fmtDate(date)}</div>${['accomplished','learned','wentWell','improve','gratitude'].map((k,i)=>`<div class="field"><label>${['What did I accomplish?','What did I learn?','What went well?','What could improve tomorrow?','A moment worth remembering'][i]}</label><textarea data-review="${k}" placeholder="Write freely...">${esc(r[k]||'')}</textarea></div>`).join('')}${btn('Save reflection','saveReview','primary')}<div class="notice sectiongap">Workout: ${entries('workouts').length?'logged':'not logged'} · Connection: ${entries('relationships').length?'logged':'not logged'} · Expenses: ${rupee(entries('expenses').reduce((s,x)=>s+Number(x.amount),0))}</div>`,'span7')}${section('Weekly overview',`<div class="flex between"><button class="secondary small" data-action="prevweek">←</button><span class="sub">${days[0]} – ${days[6]}</span><button class="secondary small" data-action="nextweek">→</button></div><div class="sectiongap">${[['Academic + technical',cat(['Academics','Technical learning'])+' + '+hours(totalActual(learn))+' study records'],['Internship',cat(['Internship'])],['Personal projects',cat(['Personal projects'])],['Gym',w.length+' sessions'],['People',cat(['Mother','Family','Girlfriend','Friends'])+' + '+hours(totalActual(rel))+' moment records'],['Leisure',cat(['Entertainment','Gaming','Travel'])],['Sleep',cat(['Sleep'])],['Expenses',rupee(e.reduce((s,x)=>s+Number(x.amount),0))],['Planned vs completed',a.filter(x=>x.status==='completed').length+' / '+a.length]].map(([n,v])=>`<div class="rowitem"><div class="rowbody"><strong>${n}</strong></div><strong>${v}</strong></div>`).join('')}</div><p class="sub">Study and relationship records are shown separately to avoid silently counting them twice. Weekly totals reflect only what you record.</p>`,'span5')}${section('Weekly time distribution',categoryBars(days),'span12')}</div>`}
function settingsView(){return heading('Settings & your data','Local-first records with optional Cloudflare D1 synchronization.')+`<div class="grid">${section('Internship schedule',`<div class="notice">Your internship begins on <strong>20 November 2026</strong>. Its hours have not been confirmed.</div><div class="field"><label>Confirmed hours or note</label><input id="internshipHours" value="${esc(db.internshipHours)}" placeholder="Unconfirmed"></div>${btn('Save internship note','saveHours','primary')}<p class="sub">Changing the note never alters historical records or schedules.</p>`,'span6')}${section('Backup & restore',`<p class="muted">Export JSON regularly, especially before changing phones or clearing Safari data. Cloud uploads are automatic after connection, but cloud downloads are manual.</p><div class="flex">${btn('Export backup','export','primary')}${btn('Import backup','import')}</div><p class="sub">Import replaces all current LifeOS records after confirmation.</p>`,'span6')}${section('Appearance & data safety',`<div class="flex">${btn('Choose nature theme','theme')}${btn('Delete all data','clear','danger')}</div><p class="sub">Deleting browser site data can erase local records. Export before doing so.</p>`,'span6')}${section('iPhone installation',`<p>Publish the files to an HTTPS host. Open the website in Safari → Share → Add to Home Screen → enable Open as Web App if offered → Add.</p><p class="sub">The app can launch standalone and load cached assets offline after its first successful visit. Browser storage can still be cleared by iOS or the user.</p>`,'span6')}</div>`}
function render(){document.body.classList.remove('light');document.querySelector('#theme').textContent='◐';document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));document.querySelector('#main').innerHTML=tab==='home'?home():tab==='planner'?planner():tab==='log'?logger():tab==='track'?track():tab==='review'?review():tab==='ai'?aiView():tab==='shared'?sharedView():settingsView()}
const select=(arr,v)=>arr.map(x=>`<option value="${esc(x)}" ${x===v?'selected':''}>${esc(x)}</option>`).join('');
function field(name,label,value='',type='text',required=false){return `<div class="field"><label for="f_${name}">${label}</label><input id="f_${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`}
function dropdown(name,label,arr,v){return `<div class="field"><label for="f_${name}">${label}</label><select id="f_${name}" name="${name}">${select(arr,v)}</select></div>`}
function textarea(name,label,value=''){return `<div class="field"><label for="f_${name}">${label}</label><textarea id="f_${name}" name="${name}">${esc(value)}</textarea></div>`}
function domainField(x){return `<div class="field"><label for="f_domain">Life domain (optional)</label><select id="f_domain" name="domain"><option value="">Auto from category</option>${LifeOSDomains.domains.map(([key,name])=>`<option value="${key}" ${x.domain===key?'selected':''}>${esc(name)}</option>`).join('')}</select></div>`}
function fieldsFor(type,x){let d=x.date||date;switch(type){case 'activities':return field('title','Activity',x.title,'text',true)+`<div class="formgrid">${field('date','Date',d,'date',true)}${dropdown('category','Category',categories,x.category||'Technical learning')}${domainField(x)}${field('start','Planned start',x.start||'','time')}${field('end','Planned end',x.end||'','time')}${field('endDate','End date (optional; overnight)',x.endDate||'','date')}${dropdown('priority','Priority',['Low','Normal','High'],x.priority||'Normal')}${dropdown('status','Status',['planned','in_progress','paused','completed','skipped'],x.status||'planned')}${field('actual','Recorded minutes (optional)',x.actual??'','number')}</div>`+textarea('notes','Notes',x.notes);case 'logs':return field('title','What did you do?',x.title,'text',true)+`<div class="formgrid">${field('date','Date',d,'date',true)}${dropdown('category','Category',categories,x.category||'Technical learning')}${domainField(x)}${field('start','Actual start',x.start||'','time')}${field('end','Actual end',x.end||'','time')}${field('endDate','Actual end date (overnight)',x.endDate||'','date')}${field('actual','Actual minutes',x.actual??'','number')}</div>`+textarea('notes','Notes',x.notes);case 'learning':return field('subject','Subject / skill',x.subject,'text',true)+field('topic','Topic',x.topic,'text',true)+`<div class="formgrid">${field('date','Date',d,'date',true)}${field('actual','Minutes studied',x.actual||0,'number')}${dropdown('status','Status',['In progress','Completed','Revisit'],x.status||'In progress')}${dropdown('revision','Revision needed?',['No','Yes'],x.revision||'No')}</div>`+field('resource','Learning resource',x.resource)+textarea('notes','Notes',x.notes);case 'projects':return field('name','Project',x.name,'text',true)+dropdown('status','Status',['Not started','Active','Paused','Completed'],x.status||'Not started')+field('progress','Progress % (optional)',x.progress??'','number')+textarea('notes','Notes / next steps',x.notes);case 'workouts':return field('date','Workout date',d,'date',true)+dropdown('type','Workout type',['Push','Pull','Legs','Full body','Cardio','Mobility','Recovery','Rest','Other'],x.type||'Push')+field('exercise','Exercise',x.exercise)+`<div class="formgrid">${field('sets','Sets',x.sets||'','number')}${field('reps','Reps',x.reps||'','number')}${field('weight','Weight (kg)',x.weight||'','number')}${field('bodyweight','Body weight (kg)',x.bodyweight||'','number')}${field('actual','Duration (minutes)',x.actual||'','number')}${dropdown('recovery','Recovery',['Not specified','Good','Moderate','Needs rest'],x.recovery||'Not specified')}${dropdown('pr','Personal record?',['No','Yes'],x.pr||'No')}</div>`+textarea('notes','Notes',x.notes);case 'relationships':return dropdown('person','With whom?',['Mother','Family','Girlfriend','Friends','Myself','Other'],x.person||'Mother')+field('date','Date',d,'date',true)+dropdown('kind','Type',['Quality time','Call','Conversation','Outing','Shared experience','Other'],x.kind||'Quality time')+field('actual','Minutes',x.actual||'','number')+textarea('notes','Memory / meaningful moment',x.notes);case 'expenses':return field('amount','Amount (₹)',x.amount||'','number',true)+field('date','Date',d,'date',true)+dropdown('category','Category',expenseCats,x.category||'Food')+dropdown('method','Payment method',['UPI','Cash','Card','Bank transfer','Other'],x.method||'UPI')+field('description','Description',x.description)}}
let editing=null;
function openForm(type,entryId){let x=entryId?db[type].find(z=>z.id===entryId):null;if(entryId&&!x)return;editing={type,id:entryId||null};document.querySelector('#modalTitle').textContent=(x?'Edit ':'Add ')+({activities:'planned activity',logs:'actual activity',learning:'study session',projects:'project',workouts:'workout',relationships:'moment',expenses:'expense'}[type]);document.querySelector('#fields').innerHTML=fieldsFor(type,x||{});document.querySelector('#deleteEntry').hidden=!x;document.querySelector('#modal').showModal()}
function numberFields(o){['actual','amount','weight','sets','reps','bodyweight'].forEach(k=>{if(k in o)o[k]=o[k]===''?0:Number(o[k])});if('progress'in o)o.progress=o.progress===''?null:Number(o.progress);return o}
function saveForm(){let f=document.querySelector('#entryForm');if(!f.reportValidity())return;let x=numberFields(Object.fromEntries(new FormData(f).entries()));if(x.start&&x.end&&x.start===x.end&&(!x.endDate||x.endDate===x.date)){alert('Start and end cannot be identical on the same date.');return}if(editing.type==='activities'&&x.start&&x.end){if(!x.endDate)x.endDate=timeMinutes(x.end)<timeMinutes(x.start)?addDays(x.date,1):x.date;const startAt=new Date(x.date+'T'+x.start+':00'),endAt=new Date(x.endDate+'T'+x.end+':00');if(endAt<=startAt){alert('End date and time must be later than the start.');return}}if('actual'in x&&(!Number.isFinite(x.actual)||x.actual<0)){alert('Actual time cannot be negative.');return}if('amount'in x&&(!Number.isFinite(x.amount)||x.amount<0)){alert('Enter a valid nonnegative amount.');return}if('progress'in x&&x.progress!==null&&(x.progress<0||x.progress>100)){alert('Progress must be between 0 and 100.');return}if(editing.type==='logs'&&x.start&&x.end){if(!x.endDate)x.endDate=x.end<x.start?addDays(x.date,1):x.date;const a=LifeOSTime.localStamp(x.date,x.start),b=LifeOSTime.localStamp(x.endDate,x.end);if(!Number.isFinite(a)||!Number.isFinite(b)||b<=a||b-a>86400000){alert('Actual log end must follow start, within 24 hours.');return}if(x.actual===0)x.actual=Math.round((b-a)/60000);x.actualStartAt=new Date(a).toISOString();x.actualEndAt=new Date(b).toISOString();x.timingSource='user_adjusted';x.durationConfidence='medium';}if(editing.type==='activities'&&x.status==='completed'&&x.actual===0&&x.start&&x.end){/* Actual duration must be explicitly entered. */}if(editing.id){let i=db[editing.type].findIndex(z=>z.id===editing.id),old=db[editing.type][i];if(editing.type==='activities'&&x.status==='completed'&&old.status!=='completed'){x.completedAt=new Date().toISOString();x.recordedAt=x.completedAt;x.timingSource=x.actual>0?'user_adjusted':'quick_tap_only';x.durationConfidence=x.actual>0?'medium':'unknown'}if(editing.type==='activities'&&x.actual>0&&x.actual!==old.actual){x.timingSource='user_adjusted';x.durationConfidence='medium'}db[editing.type][i]={...old,...x}}else {if(editing.type==='activities'&&x.status==='completed'){x.completedAt=new Date().toISOString();x.recordedAt=x.completedAt;x.timingSource=x.actual>0?'user_adjusted':'quick_tap_only';x.durationConfidence=x.actual>0?'medium':'unknown'}db[editing.type].push({id:id(),...x})};document.querySelector('#modal').close();save();window.LifeOSV3?.toast('Entry saved')}
function download(){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lifeos-backup-'+TODAY()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function action(s){if(s==='copilot'){tab='ai';render();scrollTo(0,0);return}if(s==='shared'){tab='shared';render();scrollTo(0,0);return}if(s==='ringDetails'){progressDetails();return}if(s==='reschedule'){openReschedule();return}if(s==='goPlanner'){tab='planner';render();scrollTo(0,0);return}if(s==='editNext'){const x=entries('activities').filter(x=>x.status==='planned').sort((a,b)=>(a.start||'99:99').localeCompare(b.start||'99:99'))[0];if(x)openForm('activities',x.id);return}if(s.startsWith('add:'))return openForm(s.split(':')[1]);if(s.startsWith('start:'))return startActivity(s.slice(6));if(s.startsWith('pause:'))return pauseActivity(s.slice(6));if(s.startsWith('replacement:'))return openTimingReview(s.slice(12),'skip');if(s.startsWith('status:')){let [,entryId,status]=s.split(':');if(status==='completed')return openTimingReview(entryId,'complete');if(status==='skipped')return openTimingReview(entryId,'skip');updateActivityStatus(entryId,status);return}if(s==='prevday'||s==='nextday'){let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+(s==='nextday'?1:-1));date=localDate(d);calendarMonth=date.slice(0,7)}else if(s==='today'){date=TODAY();calendarMonth=date.slice(0,7)}else if(s==='prevmonth'||s==='nextmonth'){let [y,m]=calendarMonth.split('-').map(Number);calendarMonth=localDate(new Date(y,m-1+(s==='nextmonth'?1:-1),1)).slice(0,7)}else if(s==='prevweek'||s==='nextweek'){weekOffset+=s==='nextweek'?1:-1}else if(s==='saveReview'){let o={};document.querySelectorAll('[data-review]').forEach(x=>o[x.dataset.review]=x.value);db.reviews[date]=o;save();return}else if(s==='budget'){db.budget=Math.max(0,Number(document.querySelector('#budget').value)||0);save();return}else if(s==='saveHours'){db.internshipHours=document.querySelector('#internshipHours').value.trim()||'Unconfirmed';save();return}else if(s==='export'){download();return}else if(s==='import'){document.querySelector('#importFile').click();return}else if(s==='clear'){if(confirm('Permanently delete all LifeOS records on this device? Export a backup first.')){if(confirm('Final confirmation: delete every entry and review?')){db=blank();save()}}return}else if(s==='cloudPull'){cloudPull();return}else if(s==='cloudPush'){cloudPush();return}else if(s==='rescheduleApply'){applyReschedule();return}else if(s==='sharedCreate'){sharedCreate();return}else if(s==='sharedAdd'){sharedAdd();return}else if(s==='sharedExport'){sharedExport();return}else if(s==='sharedImport'){document.querySelector('#sharedImportFile').click();return}else if(s==='sharedDelete'){sharedDelete();return}else if(s==='aiGenerate'){aiGenerate();return}else if(s==='aiApply'){aiApply();return}else if(s==='aiConfigure'){aiConfigure();return}else if(s==='theme'){window.LifeOSNature?.openThemeMenu();return}render()}
/* LifeOS 2.0.1: review actual time before completing or logging a replacement activity. */
let timingReview=null;
const timingDialog=()=>document.querySelector('#timingReview');
function reviewStamp(day,time){return LifeOSTime.localStamp(day,time)}
function reviewFields(){return {startDate:document.querySelector('#trStartDate'),start:document.querySelector('#trStart'),endDate:document.querySelector('#trEndDate'),end:document.querySelector('#trEnd')}}
function updateReviewDuration(){const f=reviewFields(),a=reviewStamp(f.startDate.value,f.start.value),b=reviewStamp(f.endDate.value,f.end.value),n=Math.round((b-a)/60000),el=document.querySelector('#trDuration');el.textContent=Number.isFinite(n)&&n>0&&n<=1440?`${n} minutes (${(n/60).toFixed(2)}h)`: 'Enter an end after the start (up to 24 hours)';document.querySelector('#trSave').disabled=!(Number.isFinite(n)&&n>0&&n<=1440);}
function setReviewEndOffset(offset){const f=reviewFields(),d=reviewStamp(f.endDate.value,f.end.value);if(!Number.isFinite(d))return;const n=new Date(d+offset*60000);f.endDate.value=localDate(n);f.end.value=`${String(n.getHours()).padStart(2,'0')}:${String(n.getMinutes()).padStart(2,'0')}`;updateReviewDuration()}
function reviewOffsetFromScheduled(minutes){if(!timingReview)return;const x=db.activities.find(a=>a.id===timingReview.id),span=x&&LifeOSTime.scheduledInterval(x);if(!span)return;const direction=document.querySelector('#trDirection').value==='early'?-1:1;const d=new Date(span.end+direction*minutes*60000),f=reviewFields();f.endDate.value=localDate(d);f.end.value=`${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;updateReviewDuration()}
function openTimingReview(entryId,kind){const x=db.activities.find(a=>a.id===entryId);if(!x)return;timingReview={id:entryId,kind};const span=LifeOSTime.scheduledInterval(x),start=span?new Date(span.start):new Date(),end=span?new Date(span.end):new Date(start.getTime()+30*60000),f=reviewFields();f.startDate.value=localDate(start);f.start.value=`${String(start.getHours()).padStart(2,'0')}:${String(start.getMinutes()).padStart(2,'0')}`;f.endDate.value=localDate(end);f.end.value=`${String(end.getHours()).padStart(2,'0')}:${String(end.getMinutes()).padStart(2,'0')}`;
 document.querySelector('#trHeading').textContent=kind==='complete'?'Complete: '+x.title:'Skipped: '+x.title;
 document.querySelector('#trExplanation').textContent=kind==='complete'?'Confirm when you actually worked. Scheduled times are prefilled as a convenience, not measured evidence.':'The scheduled activity stays skipped. Optionally record what you did instead during this time.';
 document.querySelector('#trReplacement').hidden=kind!=='skip';document.querySelector('#trTitle').value='';document.querySelector('#trCategory').innerHTML=categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');document.querySelector('#trCategory').value='Other';document.querySelector('#trDirection').value='early';document.querySelector('#trSkipOnly').hidden=kind!=='skip';document.querySelector('#trSave').textContent=kind==='complete'?'Confirm completion & time':'Skip & save replacement log';document.querySelector('#trShortcuts').hidden=!span;updateReviewDuration();timingDialog().showModal();}
function saveTimingReview(){if(!timingReview)return;const x=db.activities.find(a=>a.id===timingReview.id);if(!x)return;const f=reviewFields(),start=reviewStamp(f.startDate.value,f.start.value),end=reviewStamp(f.endDate.value,f.end.value),actual=Math.round((end-start)/60000);if(!Number.isFinite(actual)||actual<=0||actual>1440){alert('Choose valid start/end times, up to 24 hours apart.');return}const now=new Date().toISOString();
 if(timingReview.kind==='complete'){
  if(x.status==='in_progress'&&Array.isArray(x.timingIntervals)&&x.timingIntervals.length&&!confirm('Replace existing timer measurements with these manually entered times?'))return;
  x.status='completed';x.completedAt=now;x.recordedAt=now;x.actual=actual;x.actualStartAt=new Date(start).toISOString();x.actualEndAt=new Date(end).toISOString();x.timingIntervals=[];x.timingSource='user_adjusted';x.durationConfidence='medium';
 }else{
  const title=document.querySelector('#trTitle').value.trim();if(!title){alert('Enter what you did instead, or select Skip without logging.');return}
  updateActivityStatus(x.id,'skipped',{deferSave:true});db.logs.push({id:id(),title:title.slice(0,150),category:document.querySelector('#trCategory').value,date:f.startDate.value,start:f.start.value,end:f.end.value,endDate:f.endDate.value,actual,actualStartAt:new Date(start).toISOString(),actualEndAt:new Date(end).toISOString(),timingSource:'user_adjusted',durationConfidence:'medium',notes:'Replacement for skipped activity: '+x.title,sourceActivityId:x.id});
 }
 timingDialog().close();const reviewWasCompletion=timingReview.kind==='complete';timingReview=null;save();window.LifeOSV3?.toast(reviewWasCompletion?'Activity completed · time recorded':'Replacement activity logged');}
function skipWithoutLogging(){if(!timingReview||timingReview.kind!=='skip')return;updateActivityStatus(timingReview.id,'skipped',{deferSave:true});timingDialog().close();timingReview=null;save();window.LifeOSV3?.toast('Activity marked skipped')}

/* One-tap completion is valid evidence of completion, never proof of elapsed minutes. */
function totalTimedMinutes(activity){return Math.round((activity.timingIntervals||[]).reduce((sum,slot)=>{const a=Date.parse(slot.start),b=Date.parse(slot.end);return sum+(Number.isFinite(a)&&Number.isFinite(b)&&b>a?(b-a)/60000:0)},0))}
function stopOpenTimer(activity,now){if(!Array.isArray(activity.timingIntervals))return;const open=activity.timingIntervals.findLast(slot=>slot.start&&!slot.end);if(open)open.end=now}
function startActivity(entryId){const x=db.activities.find(a=>a.id===entryId);if(!x||['completed','skipped'].includes(x.status))return;if(x.status==='in_progress'){alert('This activity is already running.');return}x.timingIntervals=Array.isArray(x.timingIntervals)?x.timingIntervals:[];const now=new Date().toISOString();if(!x.actualStartAt)x.actualStartAt=now;x.timingIntervals.push({start:now,end:null});x.timingSource='explicit_timer';x.durationConfidence='high';x.status='in_progress';save()}
function pauseActivity(entryId){const x=db.activities.find(a=>a.id===entryId);if(!x||x.status!=='in_progress')return;stopOpenTimer(x,new Date().toISOString());x.actual=totalTimedMinutes(x);x.status='paused';save()}
function updateActivityStatus(entryId,status,options={}){const x=db.activities.find(a=>a.id===entryId);if(!x)return;const now=new Date().toISOString();if(status==='completed'){stopOpenTimer(x,now);x.status='completed';x.completedAt=now;x.recordedAt=now;if(Array.isArray(x.timingIntervals)&&x.timingIntervals.length){x.actualEndAt=now;x.actual=totalTimedMinutes(x);x.timingSource='explicit_timer';x.durationConfidence='high'}else if(Number(x.actual)>0){x.timingSource=x.timingSource||'user_adjusted';x.durationConfidence=x.durationConfidence||'medium'}else{x.actual=0;x.timingSource='quick_tap_only';x.durationConfidence='unknown'};}else if(status==='skipped'){stopOpenTimer(x,now);x.status='skipped';x.recordedAt=now;if(Array.isArray(x.timingIntervals)&&x.timingIntervals.length){x.actual=totalTimedMinutes(x);x.timingSource='explicit_timer';x.durationConfidence='high'}}else if(status==='planned'){if((x.timingIntervals?.length||x.completedAt||Number(x.actual)>0)&&!confirm('Reset completion and recorded timing evidence for this activity?'))return;x.status='planned';x.actual=0;delete x.completedAt;delete x.actualStartAt;delete x.actualEndAt;delete x.timingIntervals;delete x.timingSource;delete x.durationConfidence;}else return;if(!options.deferSave)save();return true}
document.querySelector('#nav').addEventListener('click',e=>{let b=e.target.closest('[data-tab]');if(b){tab=b.dataset.tab;render();scrollTo(0,0)}});
document.querySelector('#main').addEventListener('click',e=>{let edit=e.target.closest('[data-edit]'),act=e.target.closest('[data-action]'),track=e.target.closest('[data-track]'),day=e.target.closest('[data-date]');if(edit){let [type,entryId]=edit.dataset.edit.split(':');openForm(type,entryId)}else if(act)action(act.dataset.action);else if(track){trackTab=track.dataset.track;render()}else if(day){date=day.dataset.date;render()}});
document.querySelector('#main').addEventListener('change',e=>{if(e.target.id==='datePick'){date=e.target.value||TODAY();calendarMonth=date.slice(0,7);render()}else if(e.target.id==='filter'){filter=e.target.value;render()}});
document.querySelector('#main').addEventListener('input',e=>{if(e.target.id==='aiPrompt'){aiPrompt=e.target.value;return}if(e.target.id==='search'){search=e.target.value;let pos=e.target.selectionStart;render();let el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos)}});
document.querySelector('#sharedNav').addEventListener('click',()=>{tab='shared';render();scrollTo(0,0)});document.querySelector('#main').addEventListener('click',e=>{const b=e.target.closest('[data-ai-template]');if(b){aiPrompt=b.dataset.aiTemplate;tab='ai';render();const el=document.querySelector('#aiPrompt');if(el){el.focus();el.setSelectionRange(el.value.length,el.value.length)}}});document.querySelector('#settings').addEventListener('click',()=>{tab='settings';render()});document.querySelector('#theme').addEventListener('click',()=>action('theme'));
document.querySelector('#trCancel').addEventListener('click',()=>timingDialog().close());document.querySelector('#trSkipOnly').addEventListener('click',skipWithoutLogging);document.querySelector('#trForm').addEventListener('submit',e=>{e.preventDefault();saveTimingReview()});document.querySelector('#timingReview').addEventListener('click',e=>{const b=e.target.closest('[data-tr-offset]');if(b)reviewOffsetFromScheduled(Number(b.dataset.trOffset));const step=e.target.closest('[data-tr-step]');if(step)setReviewEndOffset(Number(step.dataset.trStep))});document.querySelector('#trForm').addEventListener('input',updateReviewDuration);document.querySelector('#trForm').addEventListener('change',updateReviewDuration);document.querySelector('#closeModal').addEventListener('click',()=>document.querySelector('#modal').close());document.querySelector('#entryForm').addEventListener('submit',e=>{e.preventDefault();saveForm()});document.querySelector('#deleteEntry').addEventListener('click',()=>{if(editing&&confirm('Delete this entry?')){db[editing.type]=db[editing.type].filter(x=>x.id!==editing.id);document.querySelector('#modal').close();save()}});
document.querySelector('#importFile').addEventListener('change',async e=>{let file=e.target.files[0];if(!file)return;try{let obj=JSON.parse(await file.text());if(obj.version!==1||!['activities','logs','learning','projects','workouts','relationships','expenses'].every(k=>Array.isArray(obj[k])))throw Error('Unsupported or invalid backup');if(confirm('Replace ALL current records with this backup?')){db={...blank(),...obj,sharedSpaces:Array.isArray(obj.sharedSpaces)?obj.sharedSpaces:[]};save()}}catch(err){alert('Import failed: '+err.message)}e.target.value=''});
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});render();
// Keep the selected day aligned with the device's local calendar while LifeOS is left open.
let clockDay=TODAY();function rolloverDay(){const today=TODAY();if(clockDay!==today){if(date===clockDay){date=today;calendarMonth=today.slice(0,7);render()}clockDay=today}}
setInterval(rolloverDay,30000);window.addEventListener('focus',rolloverDay);document.addEventListener('visibilitychange',()=>{if(!document.hidden)rolloverDay()});

/* Cloud sync extension: one-user revisioned snapshot. Never silently overwrite on conflict. */

// Multi-user cloud sync. Cloud state is authoritative on login; local cache is user-scoped.
let cloudRevision=window.lifeosCloudRevision||0, cloudDirty=!!window.lifeosHasPendingChanges, cloudTimer=null, cloudBusy=false;
const CLOUD_DIRTY_KEY='lifeos.cloud.dirty.'+window.lifeosUserId;
function cloudChanged(){localStorage.setItem(CLOUD_DIRTY_KEY,'1');cloudDirty=true;clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>{if(navigator.onLine)cloudPush(true)},1200)}
async function cloudRequest(method,payload){return window.lifeosApi('/sync',method,payload)}
async function cloudPull(){
 if(cloudDirty&&!confirm('You have unsynced local changes. Downloading may replace them. Continue?'))return;
 try{const remote=await cloudRequest('GET');db=remote.data?{...blank(),...remote.data,sharedSpaces:Array.isArray(remote.data.sharedSpaces)?remote.data.sharedSpaces:[]}:blank();cloudRevision=remote.revision||0;cloudDirty=false;localStorage.removeItem(CLOUD_DIRTY_KEY);localStorage.setItem(KEY,JSON.stringify(db));render();alert('Cloud records downloaded.')}catch(e){alert('Download failed: '+e.message)}
}
async function cloudPush(silent=false){
 if(cloudBusy)return;if(!cloudDirty){if(!silent)alert('All changes are synced.');return}
 cloudBusy=true;const snapshot=JSON.stringify(db);
 try{const res=await cloudRequest('PUT',{revision:cloudRevision,data:JSON.parse(snapshot)});cloudRevision=res.revision;cloudDirty=JSON.stringify(db)!==snapshot;if(!cloudDirty)localStorage.removeItem(CLOUD_DIRTY_KEY);if(cloudDirty)cloudChanged();if(!silent)alert('Saved to LifeOS Cloud.')}catch(e){cloudDirty=true;localStorage.setItem(CLOUD_DIRTY_KEY,'1');if(!silent||e.status===409)alert('Cloud sync failed: '+e.message+'\nYour local changes are still on this device. Export a backup before resolving a conflict.')}finally{cloudBusy=false}
}
window.addEventListener('online',()=>{if(cloudDirty)cloudPush(true)});
const previousSettingsView=settingsView;
settingsView=function(){return previousSettingsView()+section('Your private cloud',`<p class="sub">Signed in as ${esc(window.lifeosEmail||window.lifeosUserId)}. Data belongs only to this account. Local changes upload automatically; use Download to refresh from another device. Concurrent edits are blocked, not merged.</p><div class="flex">${btn('Download cloud copy','cloudPull')}${btn('Upload changes','cloudPush','primary small')}</div><p class="sub">If cloud sync reports a conflict, export a backup before downloading. Offline changes are held locally on this device.</p>`,'span12')};

/* LifeOS v1.2 additions: shared-space files are user-approved exchanges, not automatic cross-account sync. */
function progressDetails(){const a=dailyPlannedActivities(date),done=a.filter(x=>x.status==='completed').length,skipped=a.filter(x=>x.status==='skipped').length;alert(`${fmtDate(date)}\n\nCompleted: ${done}\nRemaining: ${a.filter(x=>x.status==='planned').length}\nSkipped: ${skipped}\nTotal: ${a.length}\n\nTap a timeline activity to edit its details.`)}
function openReschedule(){tab='planner';render();const a=entries('activities').filter(x=>x.status==='planned');const html=`<section class="card reschedule-card"><div class="life-card-heading"><h2>Smart reshuffle</h2><span class="life-soft-tag">Preview first</span></div><p class="sub">Move remaining planned activities into a new time window, preserving their durations and order. Flexible activities stay flexible. Nothing changes until you confirm.</p><div class="formgrid"><div class="field"><label for="reshuffleStart">New starting time</label><input type="time" id="reshuffleStart" value="${new Date().toTimeString().slice(0,5)}"></div><div class="field"><label for="reshuffleGap">Break between activities (minutes)</label><input type="number" min="0" max="120" value="10" id="reshuffleGap"></div></div><p class="sub">${a.length} remaining activities · Only activities with both start and end times are moved.</p>${btn('Preview & confirm reshuffle','rescheduleApply','primary')}${btn('Cancel','goPlanner')}</section>`;document.querySelector('#main').insertAdjacentHTML('afterbegin',html);document.querySelector('.reschedule-card')?.scrollIntoView({behavior:'smooth',block:'start'})}
function applyReschedule(){
 const start=document.querySelector('#reshuffleStart')?.value,gap=Number(document.querySelector('#reshuffleGap')?.value);
 if(!/^([01]\d|2[0-3]):[0-5]$/.test(start||'')||!Number.isInteger(gap)||gap<0||gap>120){alert('Choose a valid time and a break of 0–120 minutes.');return}
 const timed=entries('activities').filter(x=>x.status==='planned'&&x.start&&x.end&&activityMinutes(x)>0).sort((a,b)=>a.start.localeCompare(b.start));
 let cursor=timeMinutes(start),changes=[];
 const stamp=n=>({date:addDays(date,Math.floor(n/1440)),time:`${String(Math.floor((n%1440)/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`});
 for(const x of timed){const length=activityMinutes(x),a=stamp(cursor),b=stamp(cursor+length);changes.push({id:x.id,title:x.title,from:`${x.date} ${x.start} – ${x.endDate||x.date} ${x.end}`,date:a.date,start:a.time,endDate:b.date,end:b.time});cursor+=length+gap}
 if(!changes.length){alert('No remaining timed activities to move.');return}
 const summary=changes.map(x=>`${x.title}: ${x.from} → ${x.date} ${x.start} – ${x.endDate} ${x.end}`).join('\n');
 if(!confirm(`Apply these ${changes.length} changes?\n\n${summary}`))return;
 for(const c of changes){const x=db.activities.find(a=>a.id===c.id);if(x){x.date=c.date;x.start=c.start;x.end=c.end;x.endDate=c.endDate}}
 save();alert('Rescheduled. Changes will sync through your existing LifeOS cloud connection.');
}
function sharedView(){const spaces=Array.isArray(db.sharedSpaces)?db.sharedSpaces:[];return heading('Shared spaces','Plan together, while your personal records stay private.')+`<div class="grid">${section('Create a space',`<p class="sub">Shared spaces are collaborative plans you can exchange as JSON files. Automatic real-time collaboration needs a separate server-side sharing service; personal D1 snapshots are never exposed.</p><div class="field"><label for="spaceName">Space name</label><input id="spaceName" maxlength="80" placeholder="Weekend plans"></div>${btn('Create space','sharedCreate','primary')}`,'span6')}${section('Exchange safely',`<p class="sub">Export a selected space and send the file to someone you trust. They can import it into their LifeOS account. Importing a matching space updates its shared plan only; it never imports personal activity logs.</p><div class="flex">${btn('Export selected space','sharedExport')}${btn('Import shared space','sharedImport','primary small')}</div>`,'span6')}${spaces.length?spaces.map(space=>section(esc(space.name),`<div class="flex"><label class="sub"><input type="radio" name="spaceSelected" value="${esc(space.id)}" ${spaces[0]===space?'checked':''}> Select space</label></div><div class="life-timeline">${space.items.map(item=>`<div class="rowitem"><div class="rowbody"><strong>${esc(item.title)}</strong><small>${esc(item.date||'Flexible date')} · ${esc(item.notes||'')}</small></div></div>`).join('')||empty('No plans yet.')}</div><div class="field"><label for="spaceItem_${esc(space.id)}">New shared plan</label><input id="spaceItem_${esc(space.id)}" maxlength="150" placeholder="Coffee on Saturday"></div><div class="field"><label for="spaceDate_${esc(space.id)}">Date (optional)</label><input type="date" id="spaceDate_${esc(space.id)}"></div><div class="flex"><button class="primary small" data-space-add="${esc(space.id)}">Add plan</button><button class="danger small" data-space-delete="${esc(space.id)}">Delete space</button></div>`,'span6')).join(''):section('Your spaces',empty('Create a space to start planning together.'),'span12')}</div>`}
function sharedCreate(){const el=document.querySelector('#spaceName'),name=el?.value.trim();if(!name){alert('Enter a space name.');return}db.sharedSpaces??=[];db.sharedSpaces.push({id:id(),name:name.slice(0,80),items:[],updatedAt:new Date().toISOString()});save()}
function sharedAdd(spaceId){const space=(db.sharedSpaces||[]).find(s=>s.id===spaceId);if(!space)return;const title=document.getElementById('spaceItem_'+spaceId)?.value.trim(),d=document.getElementById('spaceDate_'+spaceId)?.value;if(!title){alert('Enter a plan.');return}space.items.push({id:id(),title:title.slice(0,150),date:d||'',notes:''});space.updatedAt=new Date().toISOString();save()}
function sharedDelete(spaceId){const space=(db.sharedSpaces||[]).find(s=>s.id===spaceId);if(space&&confirm(`Delete shared space “${space.name}” from this account?`)){db.sharedSpaces=db.sharedSpaces.filter(s=>s.id!==spaceId);save()}}
function sharedExport(){const selected=document.querySelector('input[name="spaceSelected"]:checked')?.value,space=(db.sharedSpaces||[]).find(s=>s.id===selected);if(!space){alert('Create or select a space first.');return}const blob=new Blob([JSON.stringify({format:'lifeos-shared-space-v1',space},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='lifeos-space-'+space.id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function sharedImportFile(file){if(!file||file.size>200000){alert('Choose a shared-space file smaller than 200 KB.');return}try{const obj=JSON.parse(await file.text()),space=obj.space;if(obj.format!=='lifeos-shared-space-v1'||!space||typeof space.id!=='string'||space.id.length>100||typeof space.name!=='string'||space.name.length>80||!Array.isArray(space.items)||space.items.length>200||space.items.some(x=>typeof x.title!=='string'||x.title.length>150||typeof x.date!=='string'||x.date.length>10||typeof x.notes!=='string'||x.notes.length>500)){throw Error('Invalid shared-space file')}if(!confirm(`Import “${space.name}” with ${space.items.length} plans? A matching space will be replaced.`))return;db.sharedSpaces??=[];db.sharedSpaces=db.sharedSpaces.filter(s=>s.id!==space.id);db.sharedSpaces.push({id:space.id,name:space.name,items:space.items.map(x=>({id:String(x.id||id()).slice(0,100),title:x.title,date:x.date,notes:x.notes})),updatedAt:new Date().toISOString()});save()}catch(e){alert('Import failed: '+e.message)}}
document.querySelector('#main').addEventListener('click',e=>{const add=e.target.closest('[data-space-add]'),del=e.target.closest('[data-space-delete]');if(add)sharedAdd(add.dataset.spaceAdd);if(del)sharedDelete(del.dataset.spaceDelete)});
document.querySelector('#sharedImportFile').addEventListener('change',async e=>{await sharedImportFile(e.target.files[0]);e.target.value='' });
